:root {
  /* Primary Color - Gold (金) */
  --primary: #d4af37;
  --primary-hover: #c9a23e;

  /* Background - Dark theme with silver/gold undertones */
  --bg-main: #0f0f0f;
  --bg-card: #1a1a1a;
  --bg-sidebar: #141414;
  --top-bar-bg: #1f1f1f;

  /* Border */
  --border: #2a2a2a;

  /* Text */
  --text: #e8e8e8;
  --text-muted: #a0a0a0;

  /* Top Bar */
  --top-bar-border: #3a3a3a;

  /* Additional semantic colors */
  --success: #4caf50;
  --success-light: #81c784;
  --error: #f44336;
  --error-light: #ef5350;
  --warning: #ff9800;
  --warning-light: #ffb74d;
  --info: #2196f3;
  --info-light: #64b5f6;

  /* Accent - Silver (銀) */
  --accent: #c0c0c0;
  --accent-dark: #a8a8a8;

  /* Shadow */
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 8px rgba(212, 175, 55, 0.1);
  --shadow-lg: 0 8px 16px rgba(0, 0, 0, 0.4);

  /* Opacity */
  --opacity-disabled: 0.5;
  --opacity-hover: 0.85;

  /* Spacing */
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  /* Transitions */
  --transition-fast: 150ms ease-in-out;

