function(container, apiUrl, tables) {
  const notificationList = container.querySelector('#notification-list');
  const notificationTbody = container.querySelector('#notification-tbody');
  const detailPanel = container.querySelector('#detail-panel');
  const emptyState = container.querySelector('#empty-state');
  const filterStatus = container.querySelector('#filter-status');
  const filterPriority = container.querySelector('#filter-priority');

  let allNotifications = [];
  let selectedNotificationId = null;

  // Fetch notifications
  async function loadNotifications() {
    const data = await window.aivicApi.list(0); // Table index 0: データ品質通知
    if (!data) return;
    allNotifications = data;
    renderNotificationList();
  }

  // Render notification list with filters
  function renderNotificationList() {
    const statusFilter = filterStatus.value;
    const priorityFilter = filterPriority.value;

    const filtered = allNotifications.filter(n => {
      const statusMatch = !statusFilter || n.通知ステータス === statusFilter;
      const priorityMatch = !priorityFilter || n.優先度 === priorityFilter;
      return statusMatch && priorityMatch;
    });

    notificationTbody.innerHTML = '';
    filtered.forEach(notification => {
      const row = document.createElement('tr');
      row.dataset.id = notification.通知ID;
      row.style.cssText = `
        cursor: pointer;
        border-bottom: 1px solid var(--border);
        background: ${selectedNotificationId === notification.通知ID ? 'var(--bg-card)' : 'var(--bg-main)'};
        transition: background 150ms ease-in-out;
      `;
      row.onmouseover = () => row.style.background = 'var(--bg-card)';
      row.onmouseout = () => {
        row.style.background = selectedNotificationId === notification.通知ID ? 'var(--bg-card)' : 'var(--bg-main)';
      };
      row.onclick = () => selectNotification(notification);

      const messageCell = document.createElement('td');
      messageCell.style.cssText = 'padding: 8px; text-align: left;';
      const statusBadge = document.createElement('span');
      statusBadge.style.cssText = `
        display: inline-block;
        padding: 2px 6px;
        border-radius: 3px;
        font-size: 10px;
        font-weight: 600;
        margin-right: 6px;
        ${notification.通知ステータス === '未読' ? 'background: var(--error); color: #fff;' : 'background: var(--border); color: var(--text-muted);'}
      `;
      statusBadge.textContent = notification.通知ステータス;
      messageCell.appendChild(statusBadge);
      const msgSpan = document.createElement('span');
      msgSpan.style.cssText = 'font-size: 11px; color: var(--text);';
      msgSpan.textContent = notification.通知メッセージ.substring(0, 40) + (notification.通知メッセージ.length > 40 ? '...' : '');
      messageCell.appendChild(msgSpan);
      row.appendChild(messageCell);

      const priorityCell = document.createElement('td');
      priorityCell.style.cssText = `
        padding: 8px;
        text-align: center;
        font-size: 11px;
        font-weight: 600;
        color: ${notification.優先度 === '高' ? 'var(--error-light)' : notification.優先度 === '中' ? 'var(--warning-light)' : 'var(--text-muted)'};
      `;
      priorityCell.textContent = notification.優先度;
      row.appendChild(priorityCell);

      notificationTbody.appendChild(row);
    });
  }

  // Select notification and show detail
  async function selectNotification(notification) {
    selectedNotificationId = notification.通知ID;
    renderNotificationList();

    // Fetch related error details
    const errors = await window.aivicApi.list(4); // Table index 4: 検証エラー
    const error = errors?.find(e => e.検証エラーID === notification.検証エラーID);

    if (!error) return;

    // Fetch sales data
    const salesDataList = await window.aivicApi.list(1); // Table index 1: 営業データ
    const salesData = salesDataList?.find(s => s.営業データID === error.営業データID);

    // Fetch validation rule
    const rules = await window.aivicApi.list(3); // Table index 3: 検証ルール
    const rule = rules?.find(r => r.検証ルールID === error.検証ルールID);

    // Update detail panel
    container.querySelector('#detail-error-type').textContent = error.エラー種別 || '-';
    container.querySelector('#detail-error-message').textContent = error.エラーメッセージ || '-';
    container.querySelector('#detail-priority').textContent = notification.優先度;
    container.querySelector('#detail-priority').style.background = 
      notification.優先度 === '高' ? 'var(--error)' : 
      notification.優先度 === '中' ? 'var(--warning)' : 'var(--text-muted)';

    container.querySelector('#detail-rule-name').textContent = rule?.ルール名 || '-';
    container.querySelector('#detail-rule-type').textContent = rule?.ルール種別 || '-';
    container.querySelector('#detail-rule-condition').textContent = rule?.検証条件 || '-';

    container.querySelector('#detail-customer-name').textContent = salesData?.顧客名 || '-';
    container.querySelector('#detail-transaction-date').textContent = salesData?.取引日 ? new Date(salesData.取引日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#detail-product-name').textContent = salesData?.商品名 || '-';
    container.querySelector('#detail-sales-amount').textContent = salesData?.売上金額 ? `¥${salesData.売上金額.toLocaleString()}` : '-';
    container.querySelector('#detail-billing-status').textContent = salesData?.請求状態 || '-';
    container.querySelector('#detail-detected-value').textContent = error.検出値 || '-';

    // Impact range (simplified)
    container.querySelector('#detail-impact-customer').textContent = salesData?.顧客名 || '-';
    container.querySelector('#detail-impact-service').textContent = 'データ品質検証';
    container.querySelector('#detail-impact-amount').textContent = salesData?.売上金額 ? `¥${salesData.売上金額.toLocaleString()}` : '-';

    // Auto-fix section
    const autoFixSection = container.querySelector('#auto-fix-section');
    if (rule?.自動修正フラグ) {
      autoFixSection.style.display = 'block';
      container.querySelector('#detail-fix-suggestion').textContent = rule.修正ロジック || '自動修正を実行します';
    } else {
      autoFixSection.style.display = 'none';
    }

    // Response status
    container.querySelector('#response-status').value = error.対応状況 || '未対応';
    container.querySelector('#response-comment').value = error.対応コメント || '';

    // Show detail panel
    detailPanel.style.display = 'block';
    emptyState.style.display = 'none';
  }

  // Save response
  container.querySelector('#save-response-btn').onclick = async () => {
    if (!selectedNotificationId) return;
    const status = container.querySelector('#response-status').value;
    const comment = container.querySelector('#response-comment').value;

    const notification = allNotifications.find(n => n.通知ID === selectedNotificationId);
    if (!notification) return;

    const errors = await window.aivicApi.list(4);
    const error = errors?.find(e => e.検証エラーID === notification.検証エラーID);
    if (!error) return;

    await window.aivicApi.update(4, error.検証エラーID, {
      対応状況: status,
      対応コメント: comment,
      対応日時: new Date().toISOString()
    });

    // Update notification status
    await window.aivicApi.update(0, selectedNotificationId, {
      通知ステータス: status === '修正済み' ? '解決済み' : status === '無視' ? '無視' : '対応中'
    });

    loadNotifications();
  };

  // Mark as read
  container.querySelector('#mark-read-btn').onclick = async () => {
    if (!selectedNotificationId) return;
    await window.aivicApi.update(0, selectedNotificationId, {
      通知ステータス: '既読',
      既読日時: new Date().toISOString()
    });
    loadNotifications();
  };

  // Auto-fix
  container.querySelector('#auto-fix-btn').onclick = async () => {
    if (!selectedNotificationId) return;
    const notification = allNotifications.find(n => n.通知ID === selectedNotificationId);
    if (!notification) return;

    const errors = await window.aivicApi.list(4);
    const error = errors?.find(e => e.検証エラーID === notification.検証エラーID);
    if (!error) return;

    const salesDataList = await window.aivicApi.list(1);
    const salesData = salesDataList?.find(s => s.営業データID === error.営業データID);
    if (!salesData) return;

    // Apply auto-fix (simplified: trim whitespace)
    const rules = await window.aivicApi.list(3);
    const rule = rules?.find(r => r.検証ルールID === error.検証ルールID);

    let fixedValue = error.検出値;
    if (rule?.修正ロジック?.includes('空白を削除')) {
      fixedValue = error.検出値?.trim();
    }

    // Update sales data
    await window.aivicApi.update(1, error.営業データID, {
      ...salesData,
      [error.営業データ項目メタデータID]: fixedValue
    });

    // Update error status
    await window.aivicApi.update(4, error.検証エラーID, {
      対応状況: '修正済み',
      対応日時: new Date().toISOString()
    });

    loadNotifications();
  };

  // Manual fix
  container.querySelector('#manual-fix-btn').onclick = async () => {
    if (!selectedNotificationId) return;
    const fixedValue = container.querySelector('#manual-fix-value').value;
    if (!fixedValue) return;

    const notification = allNotifications.find(n => n.通知ID === selectedNotificationId);
    if (!notification) return;

    const errors = await window.aivicApi.list(4);
    const error = errors?.find(e => e.検証エラーID === notification.検証エラーID);
    if (!error) return;

    const salesDataList = await window.aivicApi.list(1);
    const salesData = salesDataList?.find(s => s.営業データID === error.営業データID);
    if (!salesData) return;

    // Update sales data
    await window.aivicApi.update(1, error.営業データID, {
      ...salesData,
      [error.営業データ項目メタデータID]: fixedValue
    });

    // Update error status
    await window.aivicApi.update(4, error.検証エラーID, {
      対応状況: '修正済み',
      対応日時: new Date().toISOString()
    });

    container.querySelector('#manual-fix-value').value = '';
    loadNotifications();
  };

  // Filter change
  filterStatus.onchange = renderNotificationList;
  filterPriority.onchange = renderNotificationList;

  // Initial load
  loadNotifications();
}

function(container, apiUrl, tables) {
  const rulesTable = tables[0]; // 検証ルール
  const errorsTable = tables[1]; // 検証エラー
  const historyTable = tables[2]; // 検証実行履歴
  const metadataTable = tables[3]; // 営業データ項目メタデータ

  let allErrors = [];
  let selectedErrorId = null;

  // Initialize date inputs with current month
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);
  container.querySelector('[data-testid="period-start"]').valueAsDate = firstDay;
  container.querySelector('[data-testid="period-end"]').valueAsDate = lastDay;

  // Load validation rules
  async function loadRules() {
    const rules = await window.aivicApi.list(0);
    if (!rules) return;

    const rulesList = container.querySelector('#rules-list');
    rulesList.innerHTML = '';

    rules.forEach(rule => {
      const ruleEl = document.createElement('div');
      ruleEl.style.cssText = `
        padding: 8px;
        background: var(--bg-main);
        border: 1px solid var(--border);
        border-radius: 4px;
        cursor: pointer;
        font-size: 11px;
        color: var(--text);
        transition: all 0.2s ease;
      `;
      ruleEl.innerHTML = `
        <div style="font-weight: 500; margin-bottom: 2px;">${rule.ルール名 || 'ルール'}</div>
        <div style="color: var(--text-muted); font-size: 10px;">${rule.ルール種別 || '-'}</div>
      `;
      ruleEl.addEventListener('mouseenter', () => {
        ruleEl.style.borderColor = 'var(--primary)';
        ruleEl.style.background = 'rgba(212, 175, 55, 0.05)';
      });
      ruleEl.addEventListener('mouseleave', () => {
        ruleEl.style.borderColor = 'var(--border)';
        ruleEl.style.background = 'var(--bg-main)';
      });
      rulesList.appendChild(ruleEl);
    });
  }

  // Load errors
  async function loadErrors() {
    const errors = await window.aivicApi.list(1);
    if (!errors) return;

    allErrors = errors;
    renderErrorList(errors);
    updateErrorSummary(errors);
  }

  // Render error list
  function renderErrorList(errors) {
    const errorList = container.querySelector('#error-list');
    errorList.innerHTML = '';

    const searchTerm = container.querySelector('[data-testid="error-search"]').value.toLowerCase();
    const filterType = container.querySelector('[data-testid="error-filter"]').value;

    const filtered = errors.filter(err => {
      const matchSearch = !searchTerm || 
        (err.エラーメッセージ || '').toLowerCase().includes(searchTerm) ||
        (err.営業データID || '').toLowerCase().includes(searchTerm);
      const matchFilter = !filterType || (err.重要度 || '').toLowerCase() === filterType;
      return matchSearch && matchFilter;
    });

    filtered.forEach(err => {
      const errorEl = document.createElement('div');
      const severityColor = err.重要度 === 'エラー' ? 'var(--error)' : 
                           err.重要度 === '警告' ? 'var(--warning)' : 'var(--info)';

      errorEl.style.cssText = `
        padding: 8px;
        background: var(--bg-main);
        border: 1px solid var(--border);
        border-radius: 4px;
        cursor: pointer;
        font-size: 10px;
        color: var(--text);
        transition: all 0.2s ease;
      `;
      errorEl.innerHTML = `
        <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
          <div style="width: 6px; height: 6px; background: ${severityColor}; border-radius: 50%;"></div>
          <div style="flex: 1; font-weight: 500; color: var(--text);">${err.エラー種別 || '-'}</div>
          <div style="color: var(--text-muted); font-size: 9px;">${err.対応状況 || '未対応'}</div>
        </div>
        <div style="color: var(--text-muted); line-height: 1.3; word-break: break-word;">
          ${(err.エラーメッセージ || '-').substring(0, 60)}...
        </div>
      `;
      errorEl.addEventListener('click', () => {
        selectedErrorId = err.検証エラーID;
        showErrorDetail(err);
      });
      errorEl.addEventListener('mouseenter', () => {
        errorEl.style.borderColor = 'var(--primary)';
        errorEl.style.background = 'rgba(212, 175, 55, 0.05)';
      });
      errorEl.addEventListener('mouseleave', () => {
        errorEl.style.borderColor = 'var(--border)';
        errorEl.style.background = 'var(--bg-main)';
      });
      errorList.appendChild(errorEl);
    });
  }

  // Show error detail
  function showErrorDetail(err) {
    const panel = container.querySelector('#error-detail-panel');
    container.querySelector('#detail-sales-id').textContent = err.営業データID || '-';
    container.querySelector('#detail-rule-name').textContent = err.検証ルールID || '-';
    container.querySelector('#detail-error-type').textContent = err.エラー種別 || '-';
    container.querySelector('#detail-severity').textContent = err.重要度 || '-';
    container.querySelector('#detail-message').textContent = err.エラーメッセージ || '-';
    container.querySelector('#detail-detected').textContent = err.検出値 || '-';
    container.querySelector('#detail-expected').textContent = err.期待値 || '-';

    // Generate suggestion based on error type
    let suggestion = '修正提案: ';
    if (err.エラー種別 === '必須項目不足') {
      suggestion += '必須項目を入力してください。';
    } else if (err.エラー種別 === '形式不正') {
      suggestion += '指定された形式で入力し直してください。';
    } else if (err.エラー種別 === '値域外') {
      suggestion += `期待値 (${err.期待値}) の範囲内で入力してください。`;
    } else if (err.エラー種別 === '重複') {
      suggestion += '既に登録されている値です。別の値を入力してください。';
    } else {
      suggestion += 'データを確認して修正してください。';
    }
    container.querySelector('#detail-suggestion').textContent = suggestion;

    panel.style.display = 'block';
  }

  // Update error summary
  function updateErrorSummary(errors) {
    const errorCount = errors.filter(e => e.重要度 === 'エラー').length;
    const warningCount = errors.filter(e => e.重要度 === '警告').length;
    const totalCount = errors.length;
    const targetCount = container.querySelector('[data-testid="period-start"]').value ? 
      Math.floor(Math.random() * 500) + 100 : 0;

    container.querySelector('#error-count').textContent = errorCount;
    container.querySelector('#warning-count').textContent = warningCount;
    container.querySelector('#target-count').textContent = targetCount;

    const qualityScore = targetCount > 0 ? 
      Math.max(0, Math.round((1 - totalCount / targetCount) * 100)) : 100;
    container.querySelector('#quality-score').textContent = qualityScore + '%';

    // Error classification
    const classification = {};
    errors.forEach(err => {
      const type = err.エラー種別 || '不明';
      classification[type] = (classification[type] || 0) + 1;
    });

    const classEl = container.querySelector('#error-classification');
    classEl.innerHTML = '';
    Object.entries(classification).forEach(([type, count]) => {
      const bar = document.createElement('div');
      bar.style.cssText = `
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 10px;
      `;
      bar.innerHTML = `
        <div style="width: 100px; color: var(--text-muted);">${type}</div>
        <div style="flex: 1; height: 4px; background: var(--border); border-radius: 2px; overflow: hidden;">
          <div style="height: 100%; background: var(--primary); width: ${Math.min(count * 10, 100)}%;"></div>
        </div>
        <div style="width: 30px; text-align: right; color: var(--text);">${count}件</div>
      `;
      classEl.appendChild(bar);
    });
  }

  // Execute validation
  container.querySelector('[data-testid="execute-validation-btn"]').addEventListener('click', async () => {
    const startDate = container.querySelector('[data-testid="period-start"]').value;
    const endDate = container.querySelector('[data-testid="period-end"]').value;

    if (!startDate || !endDate) {
      alert('検証対象期間を選択してください。');
      return;
    }

    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    // Simulate validation progress
    for (let i = 0; i <= 100; i += 10) {
      progressBar.style.width = i + '%';
      progressText.textContent = i + '%';
      await new Promise(resolve => setTimeout(resolve, 200));
    }

    // Reload errors
    await loadErrors();
    alert('検証が完了しました。');
  });

  // Search and filter
  container.querySelector('[data-testid="error-search"]').addEventListener('input', () => {
    renderErrorList(allErrors);
  });

  container.querySelector('[data-testid="error-filter"]').addEventListener('change', () => {
    renderErrorList(allErrors);
  });

  // Close detail panel
  container.querySelector('#close-detail-btn').addEventListener('click', () => {
    container.querySelector('#error-detail-panel').style.display = 'none';
  });

  // Mark resolved
  container.querySelector('[data-testid="mark-resolved-btn"]').addEventListener('click', async () => {
    if (selectedErrorId) {
      await window.aivicApi.update(1, selectedErrorId, { 対応状況: '修正済み' });
      await loadErrors();
      container.querySelector('#error-detail-panel').style.display = 'none';
      alert('エラーを修正済みにしました。');
    }
  });

  // Ignore error
  container.querySelector('[data-testid="ignore-error-btn"]').addEventListener('click', async () => {
    if (selectedErrorId) {
      await window.aivicApi.update(1, selectedErrorId, { 対応状況: '無視' });
      await loadErrors();
      container.querySelector('#error-detail-panel').style.display = 'none';
    }
  });

  // Initial load
  loadRules();
  loadErrors();
}

function(container, apiUrl, tables) {
  const validateBtn = container.querySelector('[data-testid="validate-button"]');
  const aggregateBtn = container.querySelector('[data-testid="aggregate-button"]');
  const confirmBtn = container.querySelector('[data-testid="confirm-button"]');
  const exportBtn = container.querySelector('[data-testid="export-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  const adjustBtn = container.querySelector('[data-testid="adjust-button"]');
  const errorDetailBtn = container.querySelector('[data-testid="error-detail-button"]');
  const errorHistoryBtn = container.querySelector('[data-testid="error-history-button"]');

  const errorDetailModal = container.querySelector('#error-detail-modal');
  const errorDetailClose = container.querySelector('[data-testid="error-detail-close"]');
  const confirmModal = container.querySelector('#confirm-modal');
  const confirmCancel = container.querySelector('[data-testid="confirm-cancel"]');
  const confirmOk = container.querySelector('[data-testid="confirm-ok"]');

  let validationErrors = [];
  let billingData = [];

  // Load initial data
  async function loadData() {
    try {
      const errors = await window.aivicApi.list(5); // 検証エラーテーブル
      validationErrors = errors || [];
      updateErrorList();

      const billing = await window.aivicApi.list(9); // 顧客別請求額
      billingData = billing || [];
      updateBillingLists();
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  function updateErrorList() {
    const tbody = container.querySelector('#error-tbody');
    tbody.innerHTML = '';
    if (validationErrors.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">エラーなし</td></tr>';
    } else {
      validationErrors.slice(0, 10).forEach(err => {
        const row = document.createElement('tr');
        row.style.background = 'rgba(244,67,54,0.05)';
        row.innerHTML = `
          <td style="padding: 8px; border-bottom: 1px solid var(--border);">${err.営業データID || '-'}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border);">${err.エラー種別 || '-'}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border);">${err.エラーメッセージ || '-'}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border); text-align: center; color: #ef5350;">${err.重要度 || '警告'}</td>
        `;
        tbody.appendChild(row);
      });
    }
    container.querySelector('[data-testid="error-count"]').textContent = validationErrors.length;
  }

  function updateBillingLists() {
    const custTbody = container.querySelector('#customer-billing-tbody');
    custTbody.innerHTML = '';
    if (billingData.length === 0) {
      custTbody.innerHTML = '<tr><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
    } else {
      billingData.slice(0, 10).forEach(bill => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td style="padding: 8px; border-bottom: 1px solid var(--border);">${bill.顧客ID || '-'}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border); text-align: right;">¥${(bill.請求額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border); text-align: right;">¥${(bill.税額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border); text-align: right;">¥${(bill.請求額合計 || 0).toLocaleString()}</td>
          <td style="padding: 8px; border-bottom: 1px solid var(--border); text-align: center;"><span style="background: rgba(76,175,80,0.2); color: #81c784; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${bill.請求ステータス || '下書き'}</span></td>
        `;
        custTbody.appendChild(row);
      });
    }
  }

  validateBtn.addEventListener('click', async () => {
    const startDate = container.querySelector('[data-testid="period-start"]').value;
    const endDate = container.querySelector('[data-testid="period-end"]').value;
    if (!startDate || !endDate) {
      alert('期間を指定してください');
      return;
    }
    // Simulate validation
    validationErrors = [
      { 営業データID: 'data-001', エラー種別: '必須項目不足', エラーメッセージ: '顧客名が空白です', 重要度: '致命的' },
      { 営業データID: 'data-002', エラー種別: '形式不正', エラーメッセージ: 'メールアドレス形式が不正です', 重要度: '警告' }
    ];
    updateErrorList();
  });

  aggregateBtn.addEventListener('click', async () => {
    if (validationErrors.length > 0) {
      alert('検証エラーを解決してから集計してください');
      return;
    }
    billingData = [
      { 顧客ID: '顧客A', 請求額: 500000, 税額: 50000, 請求額合計: 550000, 請求ステータス: '確定' },
      { 顧客ID: '顧客B', 請求額: 300000, 税額: 30000, 請求額合計: 330000, 請求ステータス: '確定' }
    ];
    updateBillingLists();
  });

  confirmBtn.addEventListener('click', () => {
    confirmModal.style.display = 'flex';
  });

  confirmCancel.addEventListener('click', () => {
    confirmModal.style.display = 'none';
  });

  confirmOk.addEventListener('click', async () => {
    confirmModal.style.display = 'none';
    alert('請求を確定しました');
  });

  cancelBtn.addEventListener('click', () => {
    if (confirm('処理をキャンセルしますか？')) {
      validationErrors = [];
      billingData = [];
      updateErrorList();
      updateBillingLists();
    }
  });

  exportBtn.addEventListener('click', () => {
    const csv = ['顧客名,請求額,税額,合計'];
    billingData.forEach(b => {
      csv.push(`${b.顧客ID},${b.請求額},${b.税額},${b.請求額合計}`);
    });
    const blob = new Blob(['\uFEFF' + csv.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'billing_export.csv';
    a.click();
  });

  adjustBtn.addEventListener('click', async () => {
    const customer = container.querySelector('[data-testid="adjust-customer"]').value;
    const amount = container.querySelector('[data-testid="adjust-amount"]').value;
    const reason = container.querySelector('[data-testid="adjust-reason"]').value;
    if (!customer || !amount || !reason) {
      alert('すべての項目を入力してください');
      return;
    }
    alert('修正を適用しました');
  });

  errorDetailBtn.addEventListener('click', () => {
    if (validationErrors.length > 0) {
      const err = validationErrors[0];
      container.querySelector('#detail-data-id').textContent = err.営業データID || '-';
      container.querySelector('#detail-error-type').textContent = err.エラー種別 || '-';
      container.querySelector('#detail-detected-value').textContent = err.検出値 || '-';
      container.querySelector('#detail-expected-value').textContent = err.期待値 || '-';
      container.querySelector('#detail-message').textContent = err.エラーメッセージ || '-';
      errorDetailModal.style.display = 'flex';
    }
  });

  errorDetailClose.addEventListener('click', () => {
    errorDetailModal.style.display = 'none';
  });

  errorHistoryBtn.addEventListener('click', () => {
    alert('修正履歴画面へ遷移します');
    window.showScreen('scr-1782622477456');
  });

  // Close modals on backdrop click
  errorDetailModal.addEventListener('click', (e) => {
    if (e.target === errorDetailModal) {
      errorDetailModal.style.display = 'none';
    }
  });

  confirmModal.addEventListener('click', (e) => {
    if (e.target === confirmModal) {
      confirmModal.style.display = 'none';
    }
  });

  loadData();
}

function(container, apiUrl, tables) {
  const mappingTableIndex = 0;
  const validationRuleTableIndex = 1;
  const executionHistoryTableIndex = 2;
  const dataItemsTableIndex = 3;

  let currentEditingMappingId = null;
  let currentEditingRuleId = null;
  let pendingDeleteId = null;
  let pendingDeleteType = null;

  // Tab switching
  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabContents = container.querySelectorAll('.tab-content');

  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabName = btn.dataset.tab;
      tabButtons.forEach(b => {
        b.style.borderBottomColor = b.dataset.tab === tabName ? 'var(--primary)' : 'transparent';
        b.style.color = b.dataset.tab === tabName ? 'var(--text)' : 'var(--text-muted)';
      });
      tabContents.forEach(tc => tc.style.display = tc.id === `tab-${tabName}` ? 'block' : 'none');
    });
  });

  // Load data
  async function loadMappings() {
    const mappings = await window.aivicApi.list(mappingTableIndex);
    const tbody = container.querySelector('#mapping-tbody');
    tbody.innerHTML = '';
    if (mappings && mappings.length > 0) {
      mappings.forEach(m => {
        const tr = document.createElement('tr');
        tr.style.borderBottom = '1px solid var(--border)';
        tr.innerHTML = `
          <td style="padding: 8px; border-right: 1px solid var(--border);">${m.sourceItemName || '—'}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border);">${m.billingItemName || '—'}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="edit-mapping-btn" data-id="${m.id}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 11px; margin-right: 4px;">編集</button>
            <button class="delete-mapping-btn" data-id="${m.id}" style="background: transparent; border: none; color: var(--error); cursor: pointer; font-size: 11px;">削除</button>
          </td>
        `;
        tbody.appendChild(tr);
      });
    }
  }

  async function loadValidationRules() {
    const rules = await window.aivicApi.list(validationRuleTableIndex);
    const tbody = container.querySelector('#rules-tbody');
    tbody.innerHTML = '';
    let activeCount = 0, inactiveCount = 0;
    if (rules && rules.length > 0) {
      rules.forEach(r => {
        if (r.isActive) activeCount++;
        else inactiveCount++;
        const tr = document.createElement('tr');
        tr.style.borderBottom = '1px solid var(--border)';
        tr.innerHTML = `
          <td style="padding: 8px; border-right: 1px solid var(--border);">${r.ruleName || '—'}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); font-size: 11px;">${r.ruleType || '—'}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid var(--border);">${r.priority || '—'}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="edit-rule-btn" data-id="${r.id}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 11px; margin-right: 4px;">編集</button>
            <button class="delete-rule-btn" data-id="${r.id}" style="background: transparent; border: none; color: var(--error); cursor: pointer; font-size: 11px;">削除</button>
          </td>
        `;
        tbody.appendChild(tr);
      });
    }
    container.querySelector('[data-testid="total-rules-count"]').textContent = rules ? rules.length : 0;
    container.querySelector('[data-testid="active-rules-count"]').textContent = activeCount;
    container.querySelector('[data-testid="inactive-rules-count"]').textContent = inactiveCount;
  }

  async function loadExecutionHistory() {
    const history = await window.aivicApi.list(executionHistoryTableIndex);
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = '';
    if (history && history.length > 0) {
      history.slice(0, 10).forEach(h => {
        const tr = document.createElement('tr');
        tr.style.borderBottom = '1px solid var(--border)';
        const execDate = h.executedAt ? new Date(h.executedAt).toLocaleString('ja-JP') : '—';
        tr.innerHTML = `
          <td style="padding: 8px; border-right: 1px solid var(--border); font-size: 11px;">${execDate}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); font-size: 11px;">${h.executionMode || '—'}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid var(--border); font-size: 11px;">
            <span style="padding: 2px 6px; border-radius: 3px; background: ${h.validationResult === 'pass' ? 'var(--success)' : 'var(--error)'}; color: #fff;">
              ${h.validationResult === 'pass' ? '合格' : 'エラー'}
            </span>
          </td>
          <td style="padding: 8px; text-align: center; font-size: 11px;">${h.processingTimeMs || '—'}ms</td>
        `;
        tbody.appendChild(tr);
      });
    }
  }

  async function loadDataItems() {
    const items = await window.aivicApi.list(dataItemsTableIndex);
    const selects = container.querySelectorAll('[data-testid*="select"][name="sourceItemId"]');
    selects.forEach(sel => {
      sel.innerHTML = '<option value="">選択してください</option>';
      if (items && items.length > 0) {
        items.forEach(item => {
          const opt = document.createElement('option');
          opt.value = item.id;
          opt.textContent = item.itemName || item.itemCode;
          sel.appendChild(opt);
        });
      }
    });
  }

  // Mapping modal
  const mappingModal = container.querySelector('#mapping-modal');
  const mappingForm = container.querySelector('#mapping-form');
  const modalMappingForm = container.querySelector('#modal-mapping-form');

  container.querySelector('[data-testid="add-mapping-btn"]').addEventListener('click', () => {
    currentEditingMappingId = null;
    mappingForm.reset();
    mappingModal.style.display = 'flex';
  });

  container.addEventListener('click', e => {
    if (e.target.classList.contains('edit-mapping-btn')) {
      const id = e.target.dataset.id;
      currentEditingMappingId = id;
      mappingModal.style.display = 'flex';
    }
    if (e.target.classList.contains('delete-mapping-btn')) {
      pendingDeleteId = e.target.dataset.id;
      pendingDeleteType = 'mapping';
      container.querySelector('#delete-confirm-message').textContent = 'このマッピングを削除しますか？';
      container.querySelector('#delete-confirm-modal').style.display = 'flex';
    }
  });

  container.querySelector('[data-testid="modal-close-btn"]').addEventListener('click', () => {
    mappingModal.style.display = 'none';
  });

  container.querySelector('[data-testid="modal-save-btn"]').addEventListener('click', async () => {
    const formData = new FormData(modalMappingForm);
    const data = Object.fromEntries(formData);
    if (currentEditingMappingId) {
      await window.aivicApi.update(mappingTableIndex, currentEditingMappingId, data);
    } else {
      await window.aivicApi.save(mappingTableIndex, data);
    }
    mappingModal.style.display = 'none';
    loadMappings();
  });

  // Rule modal
  const ruleModal = container.querySelector('#rule-modal');
  const modalRuleForm = container.querySelector('#modal-rule-form');

  container.querySelector('[data-testid="add-rule-btn"]').addEventListener('click', () => {
    currentEditingRuleId = null;
    modalRuleForm.reset();
    ruleModal.style.display = 'flex';
  });

  container.addEventListener('click', e => {
    if (e.target.classList.contains('edit-rule-btn')) {
      currentEditingRuleId = e.target.dataset.id;
      ruleModal.style.display = 'flex';
    }
    if (e.target.classList.contains('delete-rule-btn')) {
      pendingDeleteId = e.target.dataset.id;
      pendingDeleteType = 'rule';
      container.querySelector('#delete-confirm-message').textContent = 'このルールを削除しますか？';
      container.querySelector('#delete-confirm-modal').style.display = 'flex';
    }
  });

  container.querySelector('[data-testid="modal-rule-close-btn"]').addEventListener('click', () => {
    ruleModal.style.display = 'none';
  });

  container.querySelector('[data-testid="modal-rule-save-btn"]').addEventListener('click', async () => {
    const formData = new FormData(modalRuleForm);
    const data = Object.fromEntries(formData);
    data.isActive = modalRuleForm.querySelector('[data-testid="modal-active-checkbox"]').checked;
    if (currentEditingRuleId) {
      await window.aivicApi.update(validationRuleTableIndex, currentEditingRuleId, data);
    } else {
      await window.aivicApi.save(validationRuleTableIndex, data);
    }
    ruleModal.style.display = 'none';
    loadValidationRules();
  });

  // Delete confirmation
  const deleteConfirmModal = container.querySelector('#delete-confirm-modal');
  container.querySelector('[data-testid="confirm-delete-btn"]').addEventListener('click', async () => {
    if (pendingDeleteType === 'mapping') {
      await window.aivicApi.delete(mappingTableIndex, pendingDeleteId);
      loadMappings();
    } else if (pendingDeleteType === 'rule') {
      await window.aivicApi.delete(validationRuleTableIndex, pendingDeleteId);
      loadValidationRules();
    }
    deleteConfirmModal.style.display = 'none';
  });

  container.querySelector('[data-testid="cancel-delete-btn"]').addEventListener('click', () => {
    deleteConfirmModal.style.display = 'none';
  });

  // Execution
  container.querySelector('[data-testid="run-validation-btn"]').addEventListener('click', async () => {
    const startDate = container.querySelector('[data-testid="exec-start-date"]').value;
    const endDate = container.querySelector('[data-testid="exec-end-date"]').value;
    const mode = container.querySelector('[data-testid="exec-mode-select"]').value;

    if (!startDate || !endDate || !mode) {
      alert('すべての項目を入力してください');
      return;
    }

    const result = await window.aivicApi.save(executionHistoryTableIndex, {
      startDate,
      endDate,
      executionMode: mode,
      executedAt: new Date().toISOString(),
      validationResult: 'pass'
    });

    if (result) {
      container.querySelector('[data-testid="exec-count"]').textContent = Math.floor(Math.random() * 100) + 50;
      container.querySelector('[data-testid="pass-count"]').textContent = Math.floor(Math.random() * 80) + 30;
      container.querySelector('[data-testid="error-count"]').textContent = Math.floor(Math.random() * 20);
      loadExecutionHistory();
    }
  });

  // Navigation
  container.querySelector('[data-testid="back-button"]').addEventListener('click', () => {
    window.showScreen("scr-1782622312596");
  });

  container.querySelector('[data-testid="nav-billing-button"]').addEventListener('click', () => {
    window.showScreen("scr-1782622562418");
  });

  // CSV Export
  container.querySelector('[data-testid="export-mapping-btn"]').addEventListener('click', async () => {
    const mappings = await window.aivicApi.list(mappingTableIndex);
    if (!mappings || mappings.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }
    const headers = ['営業データ項目', '請求項目コード', '請求項目名', 'マッピングタイプ'];
    const rows = mappings.map(m => [m.sourceItemName, m.billingItemCode, m.billingItemName, m.mappingType]);
    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(r => r.map(v => `"${v || ''}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'mapping_export.csv';
    link.click();
  });

  // Close modals on backdrop click
  [mappingModal, ruleModal, deleteConfirmModal].forEach(modal => {
    modal.addEventListener('click', e => {
      if (e.target === modal) modal.style.display = 'none';
    });
  });

  // Initial load
  loadDataItems();
  loadMappings();
  loadValidationRules();
  loadExecutionHistory();
}

function(container, apiUrl, tables) {
  const billingPeriodInput = container.querySelector('#billing-period');
  const customerFilter = container.querySelector('#customer-filter');
  const serviceFilter = container.querySelector('#service-filter');
  const searchBtn = container.querySelector('#search-btn');
  const executCalcBtn = container.querySelector('#execute-calc-btn');
  const exportCsvBtn = container.querySelector('#export-csv-btn');
  const backBtn = container.querySelector('#back-btn');
  const confirmModal = container.querySelector('#confirm-modal');
  const confirmCancel = container.querySelector('#confirm-cancel');
  const confirmExecute = container.querySelector('#confirm-execute');

  const validationCountEl = container.querySelector('#validation-count');
  const validationPassEl = container.querySelector('#validation-pass');
  const validationErrorEl = container.querySelector('#validation-error');
  const qualityScoreEl = container.querySelector('#quality-score');
  const errorTbody = container.querySelector('#error-tbody');
  const mappingTbody = container.querySelector('#mapping-tbody');
  const billingTbody = container.querySelector('#billing-tbody');
  const progressContainer = container.querySelector('#progress-container');
  const progressIdle = container.querySelector('#progress-idle');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const progressMessage = container.querySelector('#progress-message');

  let currentData = { errors: [], mappings: [], billing: [] };

  // Set default period to current month
  const now = new Date();
  const yearMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  billingPeriodInput.value = yearMonth;

  // Search handler
  searchBtn.addEventListener('click', async () => {
    const period = billingPeriodInput.value;
    const customer = customerFilter.value;
    const service = serviceFilter.value;

    // Simulate data fetch
    await loadValidationData(period, customer, service);
    updateQualityMetrics();
  });

  async function loadValidationData(period, customer, service) {
    try {
      // Fetch validation errors
      const errors = await window.aivicApi.list(5); // 検証エラーテーブル
      const filtered = errors.filter(e => {
        const matchPeriod = !period || (e.created_at && e.created_at.includes(period));
        return matchPeriod;
      });
      currentData.errors = filtered;
      renderErrors();

      // Fetch billing mappings
      const mappings = await window.aivicApi.list(9); // 請求対象項目マッピング
      currentData.mappings = mappings || [];
      renderMappings();

      // Fetch customer billing
      const billing = await window.aivicApi.list(10); // 顧客別請求額
      currentData.billing = billing || [];
      renderBilling();
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  function updateQualityMetrics() {
    const totalCount = currentData.errors.length + 100; // Simulated total
    const errorCount = currentData.errors.filter(e => e.重要度 === '致命的' || e.重要度 === '警告').length;
    const passCount = totalCount - errorCount;
    const score = totalCount > 0 ? Math.round((passCount / totalCount) * 100) : 100;

    validationCountEl.textContent = totalCount;
    validationPassEl.textContent = passCount;
    validationErrorEl.textContent = errorCount;
    qualityScoreEl.textContent = score + '%';
  }

  function renderErrors() {
    if (currentData.errors.length === 0) {
      errorTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">エラーなし</td></tr>';
      return;
    }
    errorTbody.innerHTML = currentData.errors.slice(0, 5).map(err => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${err.営業データID || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${err.エラー種別 || '-'}</td>
        <td style="padding: 8px; color: var(--text); font-size: 11px;">${err.エラーメッセージ || '-'}</td>
        <td style="padding: 8px; color: var(--text);"><span style="background: ${err.重要度 === '致命的' ? 'var(--error)' : 'var(--warning)'}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${err.重要度 || '-'}</span></td>
      </tr>
    `).join('');
  }

  function renderMappings() {
    if (currentData.mappings.length === 0) {
      mappingTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">マッピング情報なし</td></tr>';
      return;
    }
    mappingTbody.innerHTML = currentData.mappings.slice(0, 5).map(map => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${map.営業データ項目名 || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${map.請求項目コード || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${map.マッピングタイプ || '-'}</td>
        <td style="padding: 8px; color: var(--text);"><span style="background: var(--success); color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">有効</span></td>
      </tr>
    `).join('');
  }

  function renderBilling() {
    if (currentData.billing.length === 0) {
      billingTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">請求データなし</td></tr>';
      return;
    }
    billingTbody.innerHTML = currentData.billing.map(bill => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${bill.顧客名 || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${(bill.請求額 || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${(bill.税額 || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--primary); font-weight: 600;">¥${(bill.請求額合計 || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: center;"><span style="background: var(--info); color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${bill.請求ステータス || '下書き'}</span></td>
      </tr>
    `).join('');
  }

  // Execute calculation
  executCalcBtn.addEventListener('click', () => {
    confirmModal.style.display = 'flex';
  });

  confirmCancel.addEventListener('click', () => {
    confirmModal.style.display = 'none';
  });

  confirmExecute.addEventListener('click', async () => {
    confirmModal.style.display = 'none';
    progressIdle.style.display = 'none';
    progressContainer.style.display = 'block';

    // Simulate calculation progress
    for (let i = 0; i <= 100; i += 10) {
      progressBar.style.width = i + '%';
      progressText.textContent = i + '%';
      progressMessage.textContent = `計算中: ${i}% (${Math.floor(i / 10)}/10 ステップ)`;
      await new Promise(r => setTimeout(r, 300));
    }
    progressMessage.textContent = '計算完了';
  });

  // Export CSV
  exportCsvBtn.addEventListener('click', () => {
    const headers = ['顧客名', '請求額（税抜）', '税額', '請求額合計', 'ステータス'];
    const rows = currentData.billing.map(b => [
      b.顧客名 || '',
      b.請求額 || 0,
      b.税額 || 0,
      b.請求額合計 || 0,
      b.請求ステータス || ''
    ]);
    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(v => `"${v}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `billing-summary-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // Back button
  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1782622312596'); // 請求額集計・確認
  });

  // Initial load
  loadValidationData(yearMonth, '', '');
}

function(container, apiUrl, tables) {
  const billingMonthInput = container.querySelector('#billing-month');
  const customerSelect = container.querySelector('#customer-select');
  const serviceSelect = container.querySelector('#service-select');
  const templateSelect = container.querySelector('#template-select');
  const generateBtn = container.querySelector('#generate-btn');
  const backBtn = container.querySelector('#back-btn');
  const errorBanner = container.querySelector('#error-banner');
  const errorList = container.querySelector('#error-list');
  const confirmModal = container.querySelector('#confirm-modal');
  const modalCancel = container.querySelector('#modal-cancel');
  const modalConfirm = container.querySelector('#modal-confirm');

  // 初期月を今月に設定
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  billingMonthInput.value = `${year}-${month}`;

  // データ取得・集計
  async function loadAndAggregate() {
    try {
      // 営業データ取得
      const salesData = await window.aivicApi.list(0); // テーブルインデックス0: 営業データ
      if (!salesData) return;

      // フィルタ条件
      const selectedMonth = billingMonthInput.value;
      const selectedCustomer = customerSelect.value;
      const selectedService = serviceSelect.value;

      // 検証エラー取得
      const validationErrors = await window.aivicApi.list(5); // テーブルインデックス5: 検証エラー
      const errorCount = validationErrors ? validationErrors.length : 0;

      // エラーバナー表示
      if (errorCount > 0) {
        errorBanner.style.display = 'block';
        const errorMessages = validationErrors.slice(0, 5).map(e => `• ${e.エラーメッセージ || e.error_message}`).join('<br>');
        errorList.innerHTML = errorMessages + (validationErrors.length > 5 ? `<br>... 他 ${validationErrors.length - 5} 件` : '');
      } else {
        errorBanner.style.display = 'none';
      }

      // 検証ステータス更新
      const validationCount = salesData.length;
      const qualityScore = validationCount > 0 ? Math.max(0, 100 - (errorCount / validationCount * 100)) : 100;
      container.querySelector('#validation-count').textContent = validationCount;
      container.querySelector('#error-count').textContent = errorCount;
      container.querySelector('#quality-score').textContent = Math.round(qualityScore) + '%';
      container.querySelector('#validation-status').textContent = errorCount === 0 ? '完了' : '警告あり';

      // 請求対象データ集計
      let filteredData = salesData;
      if (selectedMonth) {
        filteredData = filteredData.filter(row => {
          const rowMonth = new Date(row.取引日 || row.transaction_date).toISOString().slice(0, 7);
          return rowMonth === selectedMonth;
        });
      }
      if (selectedCustomer) {
        filteredData = filteredData.filter(row => (row.顧客ID || row.customer_id) === selectedCustomer);
      }

      // 顧客別集計
      const customerSummary = {};
      filteredData.forEach(row => {
        const custName = row.顧客名 || row.customer_name || 'Unknown';
        const custId = row.顧客ID || row.customer_id || custName;
        const amount = row.売上金額 || row.sales_amount || 0;
        if (!customerSummary[custId]) {
          customerSummary[custId] = { name: custName, amount: 0 };
        }
        customerSummary[custId].amount += amount;
      });

      // サービス別集計
      const serviceSummary = {};
      filteredData.forEach(row => {
        const svcName = row.商品名 || row.product_name || 'Unknown';
        const amount = row.売上金額 || row.sales_amount || 0;
        if (!serviceSummary[svcName]) {
          serviceSummary[svcName] = { amount: 0 };
        }
        serviceSummary[svcName].amount += amount;
      });

      // 合計計算
      const subtotal = Object.values(customerSummary).reduce((sum, c) => sum + c.amount, 0);
      const taxAmount = Math.round(subtotal * 0.1);
      const totalAmount = subtotal + taxAmount;

      // 顧客別テーブル更新
      const customerTbody = container.querySelector('#customer-summary-tbody');
      customerTbody.innerHTML = Object.entries(customerSummary)
        .map(([id, data]) => `
          <tr style="border-bottom: 1px solid var(--border);">
            <td style="padding: 8px; color: var(--text);">${data.name}</td>
            <td style="padding: 8px; text-align: right; color: var(--primary); font-weight: 500;">¥${data.amount.toLocaleString()}</td>
          </tr>
        `)
        .join('');

      // サービス別テーブル更新
      const serviceTbody = container.querySelector('#service-summary-tbody');
      serviceTbody.innerHTML = Object.entries(serviceSummary)
        .map(([name, data]) => `
          <tr style="border-bottom: 1px solid var(--border);">
            <td style="padding: 8px; color: var(--text);">${name}</td>
            <td style="padding: 8px; text-align: right; color: var(--primary); font-weight: 500;">¥${data.amount.toLocaleString()}</td>
          </tr>
        `)
        .join('');

      // 請求額合計更新
      container.querySelector('#subtotal').textContent = `¥${subtotal.toLocaleString()}`;
      container.querySelector('#tax-amount').textContent = `¥${taxAmount.toLocaleString()}`;
      container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;

      // プレビュー情報更新
      container.querySelector('#preview-period').textContent = selectedMonth ? `${selectedMonth.slice(0, 4)}年${selectedMonth.slice(5)}月` : '全期間';
      container.querySelector('#preview-customer-count').textContent = Object.keys(customerSummary).length;
      container.querySelector('#preview-record-count').textContent = filteredData.length;

      // モーダル用データ保存
      container.dataset.totalAmount = totalAmount;
      container.dataset.subtotal = subtotal;
      container.dataset.taxAmount = taxAmount;
      container.dataset.period = selectedMonth || '全期間';
      container.dataset.customerCount = Object.keys(customerSummary).length;

    } catch (error) {
      console.error('データ集計エラー:', error);
    }
  }

  // イベントリスナー
  billingMonthInput.addEventListener('change', loadAndAggregate);
  customerSelect.addEventListener('change', loadAndAggregate);
  serviceSelect.addEventListener('change', loadAndAggregate);

  generateBtn.addEventListener('click', () => {
    const errorCount = parseInt(container.querySelector('#error-count').textContent);
    if (errorCount > 0) {
      alert('検証エラーが存在します。エラーを解決してから請求書を生成してください。');
      return;
    }
    // モーダル表示
    container.querySelector('#modal-period').textContent = container.dataset.period;
    container.querySelector('#modal-customer-count').textContent = container.dataset.customerCount;
    container.querySelector('#modal-total').textContent = `¥${parseInt(container.dataset.totalAmount).toLocaleString()}`;
    confirmModal.style.display = 'flex';
  });

  modalCancel.addEventListener('click', () => {
    confirmModal.style.display = 'none';
  });

  modalConfirm.addEventListener('click', () => {
    confirmModal.style.display = 'none';
    // 請求書生成・配信処理画面へ遷移
    window.showScreen("scr-1782622549499");
  });

  backBtn.addEventListener('click', () => {
    window.showScreen("scr-1782622312596");
  });

  // Esc キーでモーダル閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && confirmModal.style.display !== 'none') {
      confirmModal.style.display = 'none';
    }
  });

  // overlay クリックで閉じる
  confirmModal.addEventListener('click', (e) => {
    if (e.target === confirmModal) {
      confirmModal.style.display = 'none';
    }
  });

  // 初期ロード
  loadAndAggregate();
}

function(container, apiUrl, tables) {
  // State management
  let currentData = [];
  let filteredData = [];
  let baseAmount = 0;
  let discountRate = 0;
  let discountAmount = 0;
  let finalAmount = 0;
  let taxAmount = 0;

  // Mock discount rules
  const discountRules = [
    { id: 'rule-001', name: '新規顧客割引', rate: 10 },
    { id: 'rule-002', name: '大口割引', rate: 5 },
    { id: 'rule-003', name: '長期契約割引', rate: 8 }
  ];

  // Initialize
  async function init() {
    // Load sales data
    const salesData = await window.aivicApi.list(0);
    if (salesData) {
      currentData = salesData.map(row => ({
        id: row.id,
        customerName: row.顧客名 || row.customer_name || 'N/A',
        customerId: row.顧客ID || row.customer_id || '',
        serviceName: row.商品名 || row.product_name || 'N/A',
        serviceId: row.service_id || '',
        quantity: row.数量 || row.quantity || 0,
        amount: row.売上金額 || row.sales_amount || 0,
        billingStatus: row.請求状態 || row.billing_status || '未請求'
      }));
    }

    // Populate discount rules
    const rulesList = container.querySelector('#discount-rules-list');
    discountRules.forEach(rule => {
      const ruleEl = document.createElement('div');
      ruleEl.style.cssText = 'padding: 6px 8px; background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; cursor: pointer; transition: all 150ms; font-size: 11px; color: var(--text);';
      ruleEl.innerHTML = `<strong>${rule.name}</strong><br><span style="color: var(--text-muted);">${rule.rate}% 割引</span>`;
      ruleEl.addEventListener('click', () => {
        container.querySelector('#discount-rate').value = rule.rate;
        updateCalculation();
      });
      ruleEl.addEventListener('mouseover', () => {
        ruleEl.style.background = 'var(--bg-card)';
        ruleEl.style.borderColor = 'var(--primary)';
      });
      ruleEl.addEventListener('mouseout', () => {
        ruleEl.style.background = 'var(--bg-main)';
        ruleEl.style.borderColor = 'var(--border)';
      });
      rulesList.appendChild(ruleEl);
    });

    // Set default date range (current month)
    const now = new Date();
    const startMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    container.querySelector('#billing-start').value = startMonth;
    container.querySelector('#billing-end').value = startMonth;

    // Event listeners
    container.querySelector('#apply-filter-btn').addEventListener('click', applyFilter);
    container.querySelector('#apply-discount-btn').addEventListener('click', applyDiscount);
    container.querySelector('#confirm-btn').addEventListener('click', showConfirmModal);
    container.querySelector('#reset-btn').addEventListener('click', resetForm);
    container.querySelector('#confirm-ok-btn').addEventListener('click', confirmBilling);
    container.querySelector('#confirm-cancel-btn').addEventListener('click', closeConfirmModal);

    // Initial calculation
    updateCalculation();
  }

  function applyFilter() {
    const customerFilter = container.querySelector('#customer-filter').value;
    const serviceFilter = container.querySelector('#service-filter').value;

    filteredData = currentData.filter(row => {
      const matchCustomer = !customerFilter || row.customerId === customerFilter;
      const matchService = !serviceFilter || row.serviceId === serviceFilter;
      return matchCustomer && matchService && row.billingStatus === '未請求';
    });

    renderPreviewTable();
    updateCalculation();
  }

  function renderPreviewTable() {
    const tbody = container.querySelector('#preview-tbody');
    tbody.innerHTML = '';

    if (filteredData.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 11px;">該当データなし</td></tr>';
      return;
    }

    filteredData.forEach(row => {
      const tr = document.createElement('tr');
      tr.style.cssText = 'border-bottom: 1px solid var(--border);';
      tr.innerHTML = `
        <td style="padding: 6px 8px; color: var(--text); border-right: 1px solid var(--border);">${row.customerName}</td>
        <td style="padding: 6px 8px; color: var(--text); border-right: 1px solid var(--border);">${row.serviceName}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text); border-right: 1px solid var(--border);">${row.quantity}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text);">¥${row.amount.toLocaleString()}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function updateCalculation() {
    // Calculate base amount
    baseAmount = filteredData.reduce((sum, row) => sum + row.amount, 0);

    // Get discount inputs
    const rateInput = parseFloat(container.querySelector('#discount-rate').value) || 0;
    const amountInput = parseInt(container.querySelector('#discount-amount').value) || 0;

    // Calculate discount
    discountRate = rateInput;
    const rateDiscount = Math.round(baseAmount * (discountRate / 100));
    discountAmount = Math.max(rateDiscount, amountInput);

    // Calculate final amount
    const discountedAmount = Math.max(0, baseAmount - discountAmount);
    taxAmount = Math.round(discountedAmount * 0.1);
    finalAmount = discountedAmount + taxAmount;

    // Update display
    container.querySelector('#base-amount').textContent = `¥${baseAmount.toLocaleString()}`;
    container.querySelector('#discount-display').textContent = `¥${discountAmount.toLocaleString()}`;
    container.querySelector('#final-amount').textContent = `¥${finalAmount.toLocaleString()}`;
    container.querySelector('#tax-amount').textContent = `¥${taxAmount.toLocaleString()}`;

    // Update customer billing table
    renderCustomerBillingTable();

    // Update service billing table
    renderServiceBillingTable();
  }

  function renderCustomerBillingTable() {
    const tbody = container.querySelector('#customer-billing-tbody');
    tbody.innerHTML = '';

    const customerMap = {};
    filteredData.forEach(row => {
      if (!customerMap[row.customerId]) {
        customerMap[row.customerId] = { name: row.customerName, amount: 0 };
      }
      customerMap[row.customerId].amount += row.amount;
    });

    Object.values(customerMap).forEach(customer => {
      const discountRatio = baseAmount > 0 ? discountAmount / baseAmount : 0;
      const customerDiscount = Math.round(customer.amount * discountRatio);
      const customerFinal = customer.amount - customerDiscount;

      const tr = document.createElement('tr');
      tr.style.cssText = 'border-bottom: 1px solid var(--border);';
      tr.innerHTML = `
        <td style="padding: 4px 6px; color: var(--text);">${customer.name}</td>
        <td style="padding: 4px 6px; text-align: right; color: var(--primary); font-weight: 600;">¥${customerFinal.toLocaleString()}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function renderServiceBillingTable() {
    const tbody = container.querySelector('#service-billing-tbody');
    tbody.innerHTML = '';

    const serviceMap = {};
    filteredData.forEach(row => {
      if (!serviceMap[row.serviceId]) {
        serviceMap[row.serviceId] = { name: row.serviceName, amount: 0 };
      }
      serviceMap[row.serviceId].amount += row.amount;
    });

    Object.values(serviceMap).forEach(service => {
      const discountRatio = baseAmount > 0 ? discountAmount / baseAmount : 0;
      const serviceDiscount = Math.round(service.amount * discountRatio);
      const serviceFinal = service.amount - serviceDiscount;

      const tr = document.createElement('tr');
      tr.style.cssText = 'border-bottom: 1px solid var(--border);';
      tr.innerHTML = `
        <td style="padding: 4px 6px; color: var(--text);">${service.name}</td>
        <td style="padding: 4px 6px; text-align: right; color: var(--primary); font-weight: 600;">¥${serviceFinal.toLocaleString()}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function applyDiscount() {
    updateCalculation();
  }

  function showConfirmModal() {
    const modal = container.querySelector('#confirm-modal');
    container.querySelector('#confirm-base').textContent = `¥${baseAmount.toLocaleString()}`;
    container.querySelector('#confirm-discount').textContent = `¥${discountAmount.toLocaleString()}`;
    container.querySelector('#confirm-final').textContent = `¥${finalAmount.toLocaleString()}`;
    modal.style.display = 'flex';
  }

  function closeConfirmModal() {
    const modal = container.querySelector('#confirm-modal');
    modal.style.display = 'none';
  }

  async function confirmBilling() {
    // Save billing aggregation
    const billingData = {
      billing_period_start: container.querySelector('#billing-start').value,
      billing_period_end: container.querySelector('#billing-end').value,
      base_amount: baseAmount,
      discount_rate: discountRate,
      discount_amount: discountAmount,
      final_amount: finalAmount,
      tax_amount: taxAmount,
      status: '確定',
      created_at: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, billingData);
    if (saved) {
      alert('請求額が確定されました');
      closeConfirmModal();
      resetForm();
    }
  }

  function resetForm() {
    container.querySelector('#customer-filter').value = '';
    container.querySelector('#service-filter').value = '';
    container.querySelector('#discount-rate').value = '';
    container.querySelector('#discount-amount').value = '';
    filteredData = [];
    baseAmount = 0;
    discountAmount = 0;
    finalAmount = 0;
    updateCalculation();
    renderPreviewTable();
  }

  // Initialize on load
  init();
}
